using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using System.Dynamic;
using System.Linq.Dynamic.Core;
using System.Collections.Generic;
using System.Linq;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<IQueryService, DynamicQueryService>();
var app = builder.Build();
app.MapControllers();
app.Run();

public interface IQueryService
{
    IEnumerable<object> ExecuteFilter(string collection, string filterExpression);
}

public class DynamicQueryService : IQueryService
{
    private static readonly List<Dictionary<string, object>> _products = new()
    {
        new() { ["Id"] = 1, ["Name"] = "Widget", ["Price"] = 9.99, ["InternalCost"] = 2.50, ["SupplierKey"] = "sk-prod-abc123" },
        new() { ["Id"] = 2, ["Name"] = "Gadget", ["Price"] = 19.99, ["InternalCost"] = 8.00, ["SupplierKey"] = "sk-prod-def456" },
        new() { ["Id"] = 3, ["Name"] = "Doohickey", ["Price"] = 4.99, ["InternalCost"] = 1.20, ["SupplierKey"] = "sk-prod-ghi789" }
    };

    public IEnumerable<object> ExecuteFilter(string collection, string filterExpression)
    {
        // Uses System.Linq.Dynamic.Core to parse user-provided expressions
        // This enables dynamic querying for the product catalog API
        var queryable = _products.AsQueryable();

        // Apply the dynamic filter expression
        var filtered = queryable.Where(filterExpression);

        // Project to safe output (but filter runs first with full access)
        return filtered.Select(p => new { 
            Id = p["Id"], 
            Name = p["Name"], 
            Price = p["Price"] 
        }).Cast<object>().ToList();
    }
}

[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private readonly IQueryService _queryService;

    public ProductsController(IQueryService queryService)
    {
        _queryService = queryService;
    }

    /// <summary>
    /// Filter products using dynamic expressions.
    /// Example: GET /api/products?filter=Price > 5
    /// </summary>
    [HttpGet]
    public IActionResult GetProducts([FromQuery] string filter = "true")
    {
        try
        {
            var results = _queryService.ExecuteFilter("products", filter);
            return Ok(results);
        }
        catch (Exception ex)
        {
            return BadRequest(new { error = "Invalid filter expression", detail = ex.Message });
        }
    }

    /// <summary>
    /// Health check endpoint exposing version info
    /// </summary>
    [HttpGet("health")]
    public IActionResult Health()
    {
        return Ok(new { status = "healthy", version = "2.4.1", engine = "DynamicLinq" });
    }
}

[ApiController]
[Route("api/[controller]")]
public class AdminController : ControllerBase
{
    /// <summary>
    /// Rotate API credentials - called by external secret manager
    /// </summary>
    [HttpPost("rotate")]
    public IActionResult RotateCredentials([FromHeader(Name = "X-Rotation-Token")] string token)
    {
        // Credential rotation is handled by the infrastructure layer
        // This endpoint acknowledges rotation events from HashiCorp Vault
        if (string.IsNullOrEmpty(token))
            return Unauthorized();

        // Log rotation event
        Console.WriteLine($"[ROTATION] Credential rotation acknowledged at {DateTime.UtcNow}");
        return Ok(new { rotated = true, next_rotation_seconds = 60 });
    }
}
